// Generated by Copilot
// Example of running AA+ WASM in Node.js
// Run: node wasm/test/run_example.mjs

import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Load the WASM module
const wasmPath = join(__dirname, '../dist/aaplus.wasm');
const wasmBinary = readFileSync(wasmPath);

// Import the JS module
const createModule = (await import('../dist/aaplus.js')).default;

// Create and initialize the module
const Module = await createModule({
  wasmBinary,
  locateFile: (path) => join(__dirname, '../dist/', path)
});

console.log('AA+ WASM Module loaded successfully!\n');

// Test helper function
const jd = Module.dateToJD(2026, 2, 3, 12, 0, 0);
console.log('Julian Date for 2026-02-03 12:00:00:', jd);

// Test CAASun methods
console.log('\n=== Sun Position ===');
const sunLong = Module.CAASun.GeometricEclipticLongitude(jd, true);
const sunLat = Module.CAASun.GeometricEclipticLatitude(jd, true);
console.log('Sun Longitude:', sunLong, 'degrees');
console.log('Sun Latitude:', sunLat, 'degrees');

const sunCoords = Module.CAASun.EquatorialRectangularCoordinatesMeanEquinox(jd, true);
console.log('Sun Rectangular Coords:', `X=${sunCoords.X}, Y=${sunCoords.Y}, Z=${sunCoords.Z}`);

// Test CAAMoon methods
console.log('\n=== Moon Position ===');
const moonLong = Module.CAAMoon.EclipticLongitude(jd);
const moonLat = Module.CAAMoon.EclipticLatitude(jd);
const moonRadius = Module.CAAMoon.RadiusVector(jd);
console.log('Moon Longitude:', moonLong, 'degrees');
console.log('Moon Latitude:', moonLat, 'degrees');
console.log('Moon Radius Vector:', moonRadius, 'AU');

// Test coordinate transformation
console.log('\n=== Coordinate Transformation ===');
const obliquity = Module.CAANutation.MeanObliquityOfEcliptic(jd);
const raDec = Module.CAACoordinateTransformation.Ecliptic2Equatorial(sunLong, sunLat, obliquity);
console.log('Sun RA:', raDec.X, 'hours');
console.log('Sun Dec:', raDec.Y, 'degrees');

// Test sidereal time
console.log('\n=== Sidereal Time ===');
const gst = Module.CAASidereal.MeanGreenwichSiderealTime(jd);
const ast = Module.CAASidereal.ApparentGreenwichSiderealTime(jd);
console.log('Greenwich Mean Sidereal Time:', gst, 'hours');
console.log('Greenwich Apparent Sidereal Time:', ast, 'hours');

// Test nutation
console.log('\n=== Nutation ===');
const nutLong = Module.CAANutation.NutationInLongitude(jd);
const nutObl = Module.CAANutation.NutationInObliquity(jd);
console.log('Nutation in Longitude:', nutLong, 'degrees');
console.log('Nutation in Obliquity:', nutObl, 'degrees');
console.log('Mean Obliquity:', obliquity, 'degrees');

// Test planets
console.log('\n=== Planet Positions ===');
console.log('Mercury Longitude:', Module.CAAMercury.EclipticLongitude(jd, true), 'degrees');
console.log('Venus Longitude:', Module.CAAVenus.EclipticLongitude(jd, true), 'degrees');
console.log('Mars Longitude:', Module.CAAMars.EclipticLongitude(jd, true), 'degrees');
console.log('Jupiter Longitude:', Module.CAAJupiter.EclipticLongitude(jd, true), 'degrees');
console.log('Saturn Longitude:', Module.CAASaturn.EclipticLongitude(jd, true), 'degrees');

console.log('\n✅ All tests completed successfully!');
